  reg({ id: 'md2', city: 'madrid', level: 'C2', num: 2, title: 'La vida real', en: 'Admin, history and the news', goal: 'Handle formal situations and paperwork, tell the history of Madrid with all the past tenses and the passive, and understand and report the news.',
    lessons: [
      { id: 'md2l1', title: 'Quería pedir cita', en: 'Everyday admin: flat, bank, doctor and phone', skill: g, minutes: 22, vocab: [],
        intro: sec('Definition', P('In offices, banks and on the phone, Spaniards are still fairly direct — but formal Spanish uses <b>usted</b>, <b>softened verb forms</b> (imperfect and conditional of courtesy) and <b>impersonal «se»</b> on signs and forms. Formal emails follow fixed formulas.')) +
          T('Polite requests (from direct to very polite)', ['Structure', 'Example', 'Note'], [['Quiero + inf.', 'Quiero abrir una cuenta.', 'direct; fine at a counter'], ['Quería + inf.', 'Quería pedir cita con el médico.', 'imperfect of courtesy — very common'], ['¿Podría + inf.?', '¿Podría repetirme el número?', 'polite'], ['¿Le importaría + inf.?', '¿Le importaría esperar un momento?', 'very polite'], ['¿Sería posible + inf. / que + imp. subj.?', '¿Sería posible que me lo enviaran por correo?', 'formal'], ['Le agradecería que + imp. subj.', 'Le agradecería que me contestara hoy.', 'formal, written']], [1]) +
          T('Impersonal and passive «se»', ['Use', 'Example', 'English'], [['se + 3rd sing. (general rule)', 'Se debe pedir cita previa.', 'You must book an appointment.'], ['se + verb agreeing with a plural noun', 'Se necesitan dos fotos.', 'Two photos are needed.'], ['signs', 'Se alquila piso. · Se ruega silencio.', 'Flat to rent. · Silence, please.'], ['se + 3rd sing. + a + person', 'Se atiende a los clientes por orden.', 'Customers are served in order.']], [1]) +
          sec('Formal email formulas', EX([['Estimado/a señor/a:', 'Dear Sir/Madam,'], ['Me dirijo a ustedes para…', 'I am writing to you in order to…'], ['Adjunto les envío…', 'Please find attached…'], ['Les agradecería que me informaran de…', 'I would be grateful if you could inform me of…'], ['Quedo a la espera de su respuesta.', 'I look forward to your reply.'], ['Atentamente, / Un cordial saludo,', 'Yours faithfully / Kind regards,']])) +
          sec('Rules', '<ol><li>With <b>usted</b> use the 3rd person and <b>su / le</b>: <span class="es">¿Me deja su DNI? Le llamo mañana.</span></li><li>The verb with passive <b>se</b> agrees with the noun: <span class="es">Se vende piso / Se venden pisos.</span></li><li><b>agradecer / importar / ser posible + que</b> in the conditional → imperfect subjunctive: <span class="es">¿Le importaría que abriera la ventana?</span></li><li>In Spain, emails to offices start with <b>Estimado/a</b>, not «Querido/a» (that is for friends).</li></ol>') +
          sec('Examples', EX([['Buenos días, quería pedir cita para empadronarme.', 'Good morning, I’d like to book an appointment to register my address.'], ['¿Le importaría deletrearme su apellido?', 'Would you mind spelling your surname for me?'], ['Se necesita el contrato de alquiler y el pasaporte.', 'The rental contract and passport are needed.'], ['Le agradecería que me devolviera la fianza cuanto antes.', 'I would be grateful if you returned my deposit as soon as possible.'], ['Me dirijo a ustedes para poner una reclamación por una factura.', 'I am writing to you to make a complaint about a bill.']])),
        mistakes: ['❌ Se necesitan una foto → ✅ Se necesita una foto', '❌ Se vende pisos → ✅ Se venden pisos', '❌ ¿Le importaría que abro la ventana? → ✅ que abriera', '❌ Les agradecería que me envían → ✅ que me enviaran', '❌ Querido señor (to an office) → ✅ Estimado señor'],
        ex: [
          { t: 'mc', q: 'Most natural way to start at a doctor’s reception:', o: ['Dame una cita.', 'Quería pedir una cita, por favor.', 'Tú me das una cita.'], a: 1, skill: g },
          { t: 'fill', q: 'Se ___ dos fotos tamaño carné. (necesitar)', a: ['necesitan'], skill: g, ex: 'Passive se agrees with the plural noun.' },
          { t: 'fill', q: 'Se ___ habitación en piso compartido. (alquilar)', a: ['alquila'], skill: g },
          { t: 'fill', q: '¿Le importaría que ___ la ventana? (yo / abrir)', a: ['abriera', 'abriese'], skill: g },
          { t: 'fill', q: 'Les agradecería que me ___ antes del viernes. (ustedes / contestar)', a: ['contestaran', 'contestasen'], skill: g },
          { t: 'mc', q: 'Best opening for an email to your bank:', o: ['¡Hola, chicos!', 'Querido banco:', 'Estimados señores:'], a: 2, skill: g },
          { t: 'mc', q: '«Se ruega silencio» on a sign means:', o: ['Silence, please.', 'He asks for silence.', 'Silence is forbidden.'], a: 0, skill: g },
          { t: 'fix', q: 'Se vende pisos en esta calle.', a: ['se venden pisos en esta calle'], skill: g },
          { t: 'order', w: ['repetirme', 'podría', 'el', 'número'], a: ['podría repetirme el número'], en: 'Could you repeat the number for me?', skill: g },
          { t: 'tr', en: 'I would like to open a current account.', a: ['quería abrir una cuenta corriente', 'querría abrir una cuenta corriente', 'me gustaría abrir una cuenta corriente'], skill: 'writing' },
          { t: 'listen', say: 'Buenos días. Para el empadronamiento se necesita cita previa, el pasaporte y el contrato de alquiler.', o: ['You can go without an appointment.', 'You need an appointment, your passport and the rental contract.', 'You only need your passport.'], a: 1, skill: 'listening' },
          { t: 'write', prompt: 'Write a short formal email to your landlord (usted) asking for your deposit back. Use Estimado/a, Me dirijo a usted para…, Le agradecería que… and a formal closing.', sample: 'Estimada señora García: Me dirijo a usted para recordarle que dejé el piso el 30 de septiembre en perfecto estado. Le agradecería que me devolviera la fianza lo antes posible. Quedo a la espera de su respuesta. Atentamente, Kait', minWords: 35, rubric: ['Formal greeting & closing', 'usted forms', 'agradecería que + imp. subj.', 'Clear request'], skill: 'writing' }
        ] },
      { id: 'md2l2', title: 'Madrid, villa y corte', en: 'Madrid culture: history, art and festivals', skill: g, minutes: 24, vocab: [],
        intro: sec('Definition', P('Telling history needs every past tense working together: the <b>preterite</b> for events, the <b>imperfect</b> for background, the <b>pluperfect</b> for what happened before, and in guides and documentaries the <b>historical present</b>. The <b>passive</b> (ser + participle, or se) puts the monument first.')) +
          T('Past tenses in a historical story', ['Tense', 'Use', 'Example'], [['Preterite', 'completed events', 'En 1561 Felipe II trasladó la corte a Madrid.'], ['Imperfect', 'background, description, habits', 'Madrid era entonces una villa pequeña.'], ['Pluperfect', 'an earlier past', 'El Alcázar ya se había quemado cuando empezaron el Palacio.'], ['Historical present', 'vivid narration (guides, TV)', 'En 1919 Alfonso XIII inaugura el metro.']], [2]) +
          T('The passive', ['Form', 'Example', 'Note'], [['ser + participle (+ por)', 'El Prado fue inaugurado en 1819.', 'formal, written; participle agrees'], ['se + verb', 'La Plaza Mayor se terminó en 1619.', 'more common in speech'], ['active (often best)', 'Villanueva diseñó el edificio del Prado.', 'clear and natural']], [1]) +
          sec('Time expressions', EX([['en el siglo XVIII (dieciocho)', 'in the 18th century'], ['a principios / mediados / finales del siglo XIX', 'at the beginning / middle / end of the 19th century'], ['durante el reinado de Carlos III', 'during the reign of Charles III'], ['a raíz de', 'as a result of'], ['desde entonces', 'since then'], ['hoy en día', 'nowadays']])) +
          sec('Rules', '<ol><li>Centuries use <b>Roman numerals</b> and are read as cardinal numbers: <span class="es">el siglo XVII</span> = «diecisiete».</li><li>In the ser-passive the participle <b>agrees</b>: <span class="es">La plaza fue construida · Los jardines fueron diseñados</span>.</li><li>For a finished building or event use the <b>preterite</b> of ser: <span class="es">fue construido</span>, not «era construido».</li><li>Dates: <span class="es">el 15 de mayo de 1561</span> — no capital letters for months.</li></ol>') +
          sec('Examples', EX([['Durante siglos, Madrid fue una villa sin catedral.', 'For centuries Madrid was a town without a cathedral.'], ['Carlos III, a quien llamaban «el mejor alcalde de Madrid», transformó la ciudad.', 'Charles III, known as “Madrid’s best mayor”, transformed the city.'], ['El Palacio Real se construyó donde antes estaba el Alcázar.', 'The Royal Palace was built where the Alcázar used to stand.'], ['Cuando abrió el Prado, Goya ya había pintado sus retratos de la familia real.', 'When the Prado opened, Goya had already painted his portraits of the royal family.'], ['Hoy en día San Isidro se celebra con chotis y rosquillas.', 'Nowadays San Isidro is celebrated with chotis and doughnuts.']])),
        mistakes: ['❌ El palacio fue construyó → ✅ fue construido / se construyó', '❌ La plaza fue construido → ✅ fue construida', '❌ El palacio era construido en 1738 → ✅ fue construido / se empezó en 1738', '❌ en el 18 siglo → ✅ en el siglo XVIII', '❌ Cuando llegué, ya terminaron → ✅ ya habían terminado'],
        ex: [
          { t: 'fill', q: 'En 1561 Felipe II ___ la corte a Madrid. (trasladar · preterite)', a: ['trasladó', 'traslado'], skill: g },
          { t: 'fill', q: 'Entonces Madrid ___ una villa pequeña. (ser · imperfect)', a: ['era'], skill: g },
          { t: 'fill', q: 'El Prado fue ___ en 1819. (inaugurar)', a: ['inaugurado'], skill: g },
          { t: 'fill', q: 'La Plaza Mayor fue ___ en el siglo XVII. (construir)', a: ['construida'], skill: g, ex: 'Agrees with «la plaza» (feminine).' },
          { t: 'mc', q: 'Cuando empezaron el Palacio, el Alcázar ya ___ .', o: ['se quemó', 'se había quemado', 'se quemaba'], a: 1, skill: g, ex: 'Earlier past → pluperfect.' },
          { t: 'mc', q: 'Which sentence uses the historical present?', o: ['En 1919 se inauguró el metro.', 'En 1919 se inaugura el metro.', 'En 1919 se inauguraba el metro.'], a: 1, skill: g },
          { t: 'mc', q: '«el siglo XVIII» is read:', o: ['el siglo dieciocho', 'el siglo decimoctavo uno', 'el siglo ocho'], a: 0, skill: g },
          { t: 'fix', q: 'Los jardines fue diseñado por un arquitecto francés.', a: ['los jardines fueron diseñados por un arquitecto francés', 'los jardines fueron diseñados por un arquitecto frances'], skill: g },
          { t: 'match', p: [['a finales del siglo XIX', 'at the end of the 19th century'], ['durante el reinado de', 'during the reign of'], ['a raíz de', 'as a result of'], ['desde entonces', 'since then']], skill: g },
          { t: 'tr', en: 'The palace was built in the 18th century.', a: ['el palacio se construyó en el siglo xviii', 'el palacio fue construido en el siglo xviii', 'el palacio se construyó en el siglo dieciocho', 'el palacio fue construido en el siglo dieciocho'], skill: 'writing' },
          { t: 'listen', say: 'Cuando abrió el museo en mil ochocientos diecinueve, Goya todavía vivía en Madrid.', o: ['Goya died before the museum opened.', 'Goya was still living in Madrid when the museum opened.', 'Goya opened the museum.'], a: 1, skill: 'listening' },
          { t: 'write', prompt: 'Write a mini audio-guide text (5–7 sentences) about one Madrid place from the map. Use preterite, imperfect, one pluperfect and one passive.', sample: 'La Puerta del Sol era una de las puertas de la antigua muralla. En el siglo XIX la plaza se reformó y se convirtió en el centro de la ciudad. El reloj de la Real Casa de Correos fue instalado en 1866. Desde entonces, los españoles toman las uvas con sus campanadas. Cuando se puso el kilómetro cero, la plaza ya había sido el corazón de Madrid durante siglos.', minWords: 45, rubric: ['Preterite vs imperfect', 'Pluperfect', 'Passive', 'Dates & centuries'], skill: 'writing' }
        ] },
      { id: 'md2l3', title: 'Según fuentes oficiales…', en: 'Real news and media: understanding fast Spanish', skill: g, minutes: 24, vocab: [],
        intro: sec('Definition', P('News Spanish has its own grammar: <b>reported speech</b> with tense changes, precise <b>reporting verbs</b>, and the <b>conditional of rumour</b> that journalists use for information not yet confirmed. Recognising these is the key to following the radio and the papers.')) +
          T('Reported speech: tense changes after a past verb (dijo que…)', ['Direct speech', 'Reported', 'Example'], [['present', 'imperfect', '«Es pronto» → Dijo que era pronto.'], ['preterite / present perfect', 'pluperfect', '«He dimitido» → Dijo que había dimitido.'], ['future', 'conditional', '«Subirá el abono» → Anunció que subiría el abono.'], ['present subjunctive / command', 'imperfect subjunctive', '«Venid» → Nos pidió que fuéramos.'], ['imperfect / pluperfect / conditional', 'no change', '«Estaba cansado» → Dijo que estaba cansado.']], [2]) +
          T('Reporting verbs', ['Verb', 'Meaning', 'Mood after que'], [['afirmar / asegurar', 'to state / assure', 'indicative'], ['anunciar / informar de que', 'to announce / report', 'indicative'], ['señalar / explicar', 'to point out / explain', 'indicative'], ['admitir / reconocer', 'to admit', 'indicative'], ['negar', 'to deny', 'subjunctive (usually)'], ['pedir / exigir / recomendar', 'to ask / demand / recommend', 'subjunctive'], ['advertir de que', 'to warn', 'indicative']], [0]) +
          sec('The conditional of rumour', P('Journalists use the <b>conditional</b> (or conditional perfect) for facts that are reported but <b>not confirmed</b>: <span class="es">El incendio se habría originado en la cocina.</span> = The fire <i>reportedly</i> started in the kitchen. Similar markers: <span class="es">según…, al parecer, presuntamente</span>.')) +
          sec('Rules', '<ol><li>If the speech verb is in the <b>present</b> (dice que…), the tenses don’t change: <span class="es">Dice que llegará tarde.</span></li><li>If the situation is still true or still in the future, the original tense is also possible: <span class="es">Dijo que el museo abre / abría a las diez.</span></li><li><b>Según</b> is followed by the source directly: <span class="es">según el ministro</span>, not «según el ministro dice».</li><li>Time and place words change too: <span class="es">hoy → ese día, mañana → al día siguiente, aquí → allí</span>.</li></ol>') +
          sec('Examples', EX([['La alcaldesa afirmó que la obra terminaría en junio.', 'The mayor stated that the works would finish in June.'], ['El portavoz negó que hubiera recortes.', 'The spokesperson denied that there were cuts.'], ['La policía pidió a los vecinos que no salieran de casa.', 'The police asked residents not to leave their homes.'], ['Según la agencia, el retraso se debería a una avería.', 'According to the agency, the delay was reportedly due to a breakdown.'], ['Al parecer, el concierto se ha cancelado.', 'Apparently the concert has been cancelled.']])),
        mistakes: ['❌ Nos pidió que vamos → ✅ Nos pidió que fuéramos', '❌ Negó que lo había hecho → ✅ Negó que lo hubiera hecho', '❌ Según el ministro dice… → ✅ Según el ministro… / El ministro dice…', '❌ Dijo que mañana vendría (said last week) → ✅ Dijo que vendría al día siguiente', '❌ Reading «habría» as certain → ✅ it marks an unconfirmed report'],
        ex: [
          { t: 'fill', q: '«El metro abrirá toda la noche.» → Anunciaron que el metro ___ toda la noche.', a: ['abriría'], skill: g },
          { t: 'fill', q: '«He perdido las llaves.» → Dijo que ___ las llaves.', a: ['había perdido'], skill: g },
          { t: 'fill', q: '«Traed agua.» → Nos pidió que ___ agua.', a: ['trajéramos', 'trajeramos', 'trajésemos', 'trajesemos'], skill: g },
          { t: 'mc', q: 'El ministro negó que ___ un error.', o: ['había', 'hubiera', 'habrá'], a: 1, skill: g, ex: 'negar que + subjunctive.' },
          { t: 'mc', q: '«El incendio se habría originado en un bar» means:', o: ['The fire started in a bar (confirmed).', 'The fire reportedly started in a bar.', 'The fire would start in a bar.'], a: 1, skill: g },
          { t: 'mc', q: 'Which sentence is correct?', o: ['Según el alcalde dice, habrá obras.', 'Según el alcalde, habrá obras.', 'Según que el alcalde, habrá obras.'], a: 1, skill: g },
          { t: 'mc', q: '«Hoy hay huelga», dijo el lunes. → Dijo que ___ había huelga.', o: ['hoy', 'ese día', 'mañana'], a: 1, skill: g },
          { t: 'fix', q: 'La policía pidió que los vecinos no salen de casa.', a: ['la policía pidió que los vecinos no salieran de casa', 'la policia pidió que los vecinos no salieran de casa', 'la policía pidió que los vecinos no saliesen de casa'], skill: g },
          { t: 'match', p: [['afirmar', 'to state'], ['negar', 'to deny'], ['advertir', 'to warn'], ['reconocer', 'to admit']], skill: g },
          { t: 'tr', en: 'She said that she would call the next day.', a: ['dijo que llamaría al día siguiente', 'ella dijo que llamaría al día siguiente'], skill: 'writing' },
          { t: 'listen', say: 'Según fuentes municipales, la línea uno cerraría durante todo el verano por obras.', o: ['Line 1 will definitely close.', 'Line 1 would reportedly close all summer for works.', 'Line 1 has reopened after the works.'], a: 1, skill: 'listening' },
          { t: 'write', prompt: 'Report a short piece of Madrid news in 5–6 sentences: one reported statement with tense changes, one request (pedir que…), and one unconfirmed fact with the conditional.', sample: 'Esta mañana se ha cortado la Gran Vía por una manifestación. La delegada del Gobierno afirmó que la protesta terminaría a mediodía. Pidió a los conductores que evitaran el centro. Según algunos vecinos, habría más de diez mil personas. Al parecer, la policía no ha registrado incidentes.', minWords: 40, rubric: ['Tense changes', 'pedir que + imp. subj.', 'Conditional of rumour', 'News register'], skill: 'writing' }
        ] }
    ],
    review: { keyVocab: [], grammar: ['Courtesy: Quería… · ¿Podría…? · ¿Le importaría…? · Le agradecería que + imp. subj.', 'Passive se agrees with the noun: se necesita una foto / se necesitan dos fotos.', 'Formal emails: Estimado/a… · Me dirijo a ustedes para… · Atentamente.', 'History: preterite (events) · imperfect (background) · pluperfect (earlier) · historical present.', 'ser-passive: fue construido/a, fueron construidos/as.', 'Reported speech after a past verb: present → imperfect, past → pluperfect, future → conditional, command → imp. subj.', 'negar / pedir que + subjunctive.', 'Conditional of rumour: se habría originado = reportedly.'], expressions: ['Quería pedir cita.', 'Se ruega silencio.', 'Quedo a la espera de su respuesta.', 'a finales del siglo XIX', 'Según fuentes oficiales…', 'Al parecer…'], mistakes: ['Se vende pisos → Se venden pisos', 'Les agradecería que me envían → enviaran', 'La plaza fue construido → construida', 'Nos pidió que vamos → fuéramos', 'Negó que lo había hecho → hubiera hecho'] },
    exam: [
      { t: 'mc', q: 'At the bank counter, the most natural polite request:', o: ['Quería información sobre una hipoteca.', 'Dame información.', 'Informarme, por favor.'], a: 0, skill: g },
      { t: 'fill', q: 'Se ___ camareros con experiencia. (buscar)', a: ['buscan'], skill: g },
      { t: 'fill', q: 'Le agradecería que me ___ la factura por correo. (usted / enviar)', a: ['enviara', 'enviase'], skill: g },
      { t: 'mc', q: 'Best closing for a formal complaint:', o: ['¡Besos!', 'Atentamente,', 'Hasta luego,'], a: 1, skill: g },
      { t: 'fill', q: 'La catedral de la Almudena fue ___ en 1993. (consagrar)', a: ['consagrada'], skill: g },
      { t: 'mc', q: 'Cuando el Retiro se abrió al público en 1868, el antiguo palacio ya ___ casi por completo.', o: ['desapareció', 'había desaparecido', 'desaparecía'], a: 1, skill: g },
      { t: 'mc', q: 'Madrid ___ una ciudad pequeña cuando llegó la corte.', o: ['fue', 'era', 'ha sido'], a: 1, skill: g },
      { t: 'fill', q: '«Mañana subirán los precios.» → Dijo que al día siguiente ___ los precios.', a: ['subirían'], skill: g },
      { t: 'fix', q: 'El portavoz negó que el alcalde ha dimitido.', a: ['el portavoz negó que el alcalde hubiera dimitido', 'el portavoz negó que el alcalde hubiese dimitido'], skill: g },
      { t: 'mc', q: '«Los ladrones habrían escapado en moto» means:', o: ['The thieves would escape by motorbike.', 'The thieves reportedly escaped by motorbike.', 'The thieves had to escape by motorbike.'], a: 1, skill: g },
      { t: 'listen', say: 'Para pedir la tarjeta sanitaria se necesita estar empadronado. Le recomendamos que pida cita por internet.', o: ['You must be registered at the town hall; they recommend booking online.', 'You can get the card without registering.', 'You must go in person without an appointment.'], a: 0, skill: 'listening' },
      { t: 'read', text: 'MADRID. El Ayuntamiento anunció ayer que la Gran Vía cerraría al tráfico los domingos a partir de marzo. La concejala de Movilidad aseguró que la medida «mejorará la calidad del aire». Algunos comerciantes, en cambio, pidieron que se retrasara hasta el verano. Según fuentes municipales, el plan costaría unos dos millones de euros.', q: 'Which statement is NOT confirmed in the article?', o: ['The city council made an announcement.', 'Some shopkeepers asked for a delay.', 'The plan will cost about two million euros.'], a: 2, skill: 'reading' },
      { t: 'tr', en: 'The police asked us to leave the square.', a: ['la policía nos pidió que saliéramos de la plaza', 'la policia nos pidió que saliéramos de la plaza', 'la policía nos pidió que dejáramos la plaza', 'la policía nos pidió que abandonáramos la plaza', 'la policía nos pidió que saliésemos de la plaza'], skill: 'writing' },
      { t: 'write', prompt: 'Write a formal email (usted) to the city council about a problem in your street (noise, rubbish, works). Report what a neighbour told you (reported speech) and make a polite request.', sample: 'Estimados señores: Me dirijo a ustedes para informarles de un problema en la calle del Pez. Una vecina me contó que las obras habían empezado sin aviso y que durarían tres meses. Les agradecería que nos informaran del horario de las obras. Quedo a la espera de su respuesta. Atentamente, Kait', minWords: 45, rubric: ['Formal formulas', 'Reported speech', 'Polite request', 'Accuracy'], skill: 'writing' }
    ],
    homework: { id: 'hw_md2', title: 'Homework MD2 — La vida real', parts: [
      { h: 'A. Formal requests', items: [['Ask politely to book an appointment', 'Quería pedir cita, por favor.'], ['«Two documents are needed» (se)', 'Se necesitan dos documentos.'], ['Ask if they would mind waiting (usted)', '¿Le importaría esperar un momento?']] },
      { h: 'B. History', items: [['La Plaza Mayor (terminar) en 1619. (se)', 'se terminó'], ['El Prado (inaugurar) en 1819. (ser-passive)', 'fue inaugurado'], ['Madrid (ser) una villa pequeña en el siglo XVI.', 'era']] },
      { h: 'C. Reported speech', items: [['«Llegaré tarde.» → Dijo que…', 'llegaría tarde'], ['«He dimitido.» → Dijo que…', 'había dimitido'], ['«Venid pronto.» → Nos pidió que…', 'fuéramos pronto'], ['«No hay recortes.» → Negó que…', 'hubiera recortes']] },
      { h: 'D. Writing', open: true, items: [['Write a 150-word news article about an imaginary event in Madrid. Include two reporting verbs, one request with pedir que, a passive, and one unconfirmed fact with the conditional.', 'Sample: El Ayuntamiento anunció ayer que el Retiro abriría por la noche durante el verano…']], rubric: ['Reporting verbs', 'Tense changes', 'Passive', 'Conditional of rumour'] }] }
  });

  /* topics on the Madrid page now link to their lessons */
  const L = { 'Social life': 'md1l1', 'Giving opinions': 'md1l2', 'Humour': 'md1l3', 'Everyday admin': 'md2l1', 'Madrid culture': 'md2l2', 'Real news': 'md2l3' };
  MA.CITY.madrid.topics = MA.CITY.madrid.topics.map(t => { const k = Object.keys(L).find(x => t[0].startsWith(x)); return [t[0], k ? L[k] : t[1]]; });
  MA.CITY.madrid.built = true;

  /* Lucía’s chapter talks and lesson tips */
